style.css:
/*
CK_777'S PASTEL PINK ROBLOX THEME
*/
@-moz-document domain("roblox.com") {
/* =====================================
1. COLOUR PALETTE
===================================== */

:root {
    --pink-bg: #F8D0DF;
    --pink-light: #FFEAF2;
    --pink-soft: #FFD2E3;
    --pink-medium: #FFC1D9;
    --pink-strong: #F59CBD;
    --pink-strawberry: #F7A6C8;
    --pink-hover: #E987B2;
    --pink-dark: #DF78A5;
    --pink-text: #A85D7C;
    --white: #FFFFFF;
}

/* =====================================
2. MAIN BACKGROUND
===================================== */

html,
body,
#container-main,
.content,
.home-container,
.section-content {
    background-color: var(--pink-bg) !important;
}

/* =====================================
3. TOP NAVIGATION
===================================== */

#header,
.navbar,
.navbar-fixed-top {
    background: var(--pink-medium) !important;
    border-bottom: 1px solid var(--pink-strong) !important;
}

.navbar a,
#header a {
    color: var(--pink-text) !important;
}

/* Download button */

#navbar-download,
.navbar-download,
.btn-growth-md,
[href*="download"],
[aria-label*="Download"] {
    background: var(--pink-strong) !important;
    border-color: var(--pink-strong) !important;
    color: var(--pink-text) !important;
    border-radius: 20px !important;
}

/* =====================================
4. LEFT SIDEBAR
===================================== */

#navigation,
#navigation-container,
.left-navigation,
#sidebar,
.nav-list,
#navigation ul,
div.scroll-y[class~="width-[289px]"] {
    background: var(--pink-light) !important;
}

#navigation a:hover,
#navigation .list-item:hover,
.left-navigation a:hover {
    background: #FFDCE9 !important;
    border-radius: 12px !important;
}

/* =====================================
5. SEARCH BAR
===================================== */

#navbar-search,
#navbar-search-input,
input#navbar-search-input,
.search-input {
    background: var(--pink-light) !important;
    border-radius: 20px !important;
    border-color: var(--pink-strong) !important;
}

#navbar-search input {
    color: var(--pink-text) !important;
}

/* =====================================
6. SCROLLBARS
===================================== */

* {
    scrollbar-color: var(--pink-dark) var(--pink-light);
}

::-webkit-scrollbar {
    width: 8px !important;
}

::-webkit-scrollbar-track {
    background: var(--pink-light) !important;
}

::-webkit-scrollbar-thumb {
    background: var(--pink-dark) !important;
    border-radius: 20px !important;
}

/* =====================================
7. GENERAL BUTTONS
===================================== */

button,
.btn-control,
.btn-secondary-md,
.btn-more {
    border-radius: 12px !important;
}

button:hover,
.btn-control:hover {
    transition: background-color 0.2s ease;
}

/* =====================================
8. PLAY BUTTON
===================================== */

#game-details-play-button-container button,
button[data-testid="play-button"],
.btn-common-play-game-lg,
.btn-common-play-game-md,
.game-play-button {
    background: var(--pink-strawberry) !important;
    border-color: var(--pink-strawberry) !important;
    color: var(--white) !important;
    border-radius: 14px !important;
}

#game-details-play-button-container button:hover,
button[data-testid="play-button"]:hover,
.btn-common-play-game-lg:hover,
.btn-common-play-game-md:hover {
    background: var(--pink-hover) !important;
}

/* =====================================
9. FREE WITH PLUS BUTTON
===================================== */

button.foundation-web-button.bg-action-emphasis {
    background: var(--pink-strawberry) !important;
    border-color: var(--pink-strawberry) !important;
    color: var(--white) !important;
}

/* =====================================
10. PRIVATE SERVER BUTTON
===================================== */

#roproPrivateServersToggleButton {
    background: var(--pink-strawberry) !important;
    color: var(--white) !important;
    border: 1px solid var(--pink-strawberry) !important;
    border-radius: 12px !important;
}

#roproPrivateServersToggleButton:hover {
    background: var(--pink-hover) !important;
    border-color: var(--pink-hover) !important;
}

/* =====================================
11. VISIBLE PRIVATE SERVER BADGE
===================================== */

.ropro-private-servers-toggle-hint {
    background: var(--pink-strawberry) !important;
    color: var(--white) !important;
    border: 1px solid var(--pink-strawberry) !important;
    border-radius: 999px !important;
}

/* =====================================
12. SEE ALL BUTTON
===================================== */

.see-all-link,
.see-all-link-icon,
a.btn-secondary-xs.btn-more.see-all-link-icon {
    background: var(--pink-soft) !important;
    color: var(--pink-text) !important;
    border-color: var(--pink-soft) !important;
    border-radius: 12px !important;
}

.see-all-link:hover,
.see-all-link-icon:hover {
    background: var(--pink-medium) !important;
    color: var(--pink-text) !important;
}

/* =====================================
13. SERVERS / STORE / RECOMMENDED TABS
===================================== */

#horizontal-tabs,
#horizontal-tabs.nav,
#horizontal-tabs.nav-tabs,
.rbx-tabs-horizontal .nav-tabs {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

#horizontal-tabs > li,
#horizontal-tabs .rbx-tab {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

#horizontal-tabs .rbx-tab-heading,
#horizontal-tabs > li > a {
    background: var(--pink-light) !important;
    background-color: var(--pink-light) !important;
    color: var(--pink-text) !important;
    border: none !important;
    border-radius: 12px !important;
    box-shadow: none !important;
    transition: background-color 0.2s ease !important;
}

/* Active tab */

#horizontal-tabs .rbx-tab.active .rbx-tab-heading,
#horizontal-tabs .rbx-tab.active > a,
#horizontal-tabs > li.active > a {
    background: var(--pink-soft) !important;
    color: var(--pink-text) !important;
    border: none !important;
    box-shadow: none !important;
    outline: none !important;
}

/* Hover */

#horizontal-tabs .rbx-tab-heading:hover,
#horizontal-tabs > li > a:hover {
    background: var(--pink-medium) !important;
    color: var(--pink-text) !important;
    box-shadow: none !important;
}

/* Remove black underline */

#horizontal-tabs .rbx-tab.active::after,
#horizontal-tabs .rbx-tab.active::before,
#horizontal-tabs > li.active::after,
#horizontal-tabs > li.active::before,
#horizontal-tabs .rbx-tab-heading::after {
    display: none !important;
    content: none !important;
}

/* =====================================
14. ROPRO SERVER FILTERS BUTTON
===================================== */

#roproServerFiltersMiniButton,
#serverFiltersDropdown,
.ropro-server-filters-chip-trigger,
.ropro-server-filters-chip-icon-only {
    background: #FFD2E3 !important;
    background-color: #FFD2E3 !important;
    color: #A85D7C !important;
    border: 1px solid #F59CBD !important;
    border-radius: 20px !important;
    box-shadow: none !important;
}

/* Location selector button */

#regionSelectorButton,
.server-filter-option.ropro-region-chip-peeper {
    background: #FFD2E3 !important;
    background-color: #FFD2E3 !important;
    color: #A85D7C !important;
    border: 1px solid #F59CBD !important;
    border-radius: 12px !important;
    box-shadow: none !important;
}

/* RoPro filter hover */

#roproServerFiltersMiniButton:hover,
#serverFiltersDropdown:hover,
.ropro-server-filters-chip-trigger:hover,
.ropro-server-filters-chip-icon-only:hover,
#regionSelectorButton:hover,
.server-filter-option.ropro-region-chip-peeper:hover {
    background: #FFC1D9 !important;
    background-color: #FFC1D9 !important;
    color: #A85D7C !important;
    border-color: #DF78A5 !important;
}

/* RoPro filter icons */

#roproServerFiltersMiniButton svg,
#serverFiltersDropdown svg,
.ropro-server-filters-chip-trigger svg,
#regionSelectorButton svg {
    color: #A85D7C !important;
    stroke: #A85D7C !important;
}

/* RoPro filter text */

#roproServerFiltersMiniButton *,
#serverFiltersDropdown *,
.ropro-server-filters-chip-trigger *,
#regionSelectorButton * {
    color: #A85D7C !important;
}

/* =====================================
15. ROPRO FILTER DROPDOWNS
===================================== */

.light-theme #serverFiltersDropdown,
.light-theme #serverFiltersDropdown .dropdown-menu {
    background-color: #FFD2E3 !important;
    color: #A85D7C !important;
}

/* =====================================
16. EVENTS TILES
===================================== */

.experience-events-tile {
    background: var(--white) !important;
}

/* =====================================
17. FRIENDS AND MESSAGES ALIGNMENT
===================================== */

#btr-navbar-friends,
#btr-navbar-messages {
    transform: translateY(-26px) !important;
}

/* =====================================
18. STRAWBERRY CREAM SERVER CARDS
===================================== */

/* Server card background */

.card-item-public-server {
    background: #FFF0F5 !important;
    background-color: #FFF0F5 !important;
    border: 1px solid #F8D0DF !important;
    border-radius: 16px !important;
    overflow: hidden !important;
    box-shadow: none !important;
}

/* Server card details */

.card-item-public-server .rbx-public-game-server-details {
    background: #FFF0F5 !important;
    background-color: #FFF0F5 !important;
    border-radius: 0 0 16px 16px !important;
}

/* Server card hover */

.card-item-public-server:hover {
    background: #FFEAF2 !important;
    border-color: #F59CBD !important;
    transition: background 0.2s ease,
                border-color 0.2s ease !important;
}

/* =====================================
19. GENERAL CARDS AND PANELS
===================================== */

.card,
.game-card,
.friend-card,
.thumbnail-holder,
.modal-content {
    border-radius: 12px !important;
}

/* =====================================
20. HOVER AND SELECTION
===================================== */

::selection {
    background: var(--pink-strong) !important;
    color: var(--white) !important;
}

input:focus,
textarea:focus {
    border-color: var(--pink-strong) !important;
    outline-color: var(--pink-strong) !important;
}

/* =====================================
21. CHECKBOXES AND RADIO BUTTONS
===================================== */

input[type="checkbox"],
input[type="radio"] {
    accent-color: var(--pink-strong) !important;
}

/* =====================================
22. LINKS
===================================== */

a {
    accent-color: var(--pink-strong);
}

a:hover {
    color: var(--pink-dark);
}

/* =====================================
23. STRAWBERRY MILK BUY BUTTON
===================================== */

.item-details-section
.shopping-cart-buy-button.PurchaseButton,
.item-details-section
.shopping-cart-buy-button.btn-growth-lg,
.item-details-section
.shopping-cart-buy-button {
    background: var(--pink-strawberry) !important;
    background-color: var(--pink-strawberry) !important;
    border: 1px solid var(--pink-strawberry) !important;
    color: var(--white) !important;
    border-radius: 14px !important;
    box-shadow: none !important;
}

/* Buy button text */

.item-details-section
.shopping-cart-buy-button.PurchaseButton *,
.item-details-section
.shopping-cart-buy-button * {
    color: var(--white) !important;
}

/* Buy button hover */

.item-details-section
.shopping-cart-buy-button.PurchaseButton:hover,
.item-details-section
.shopping-cart-buy-button:hover {
    background: var(--pink-hover) !important;
    background-color: var(--pink-hover) !important;
    border-color: var(--pink-hover) !important;
}

/* =====================================
24. STRAWBERRY MILK SHOPPING CART CIRCLE
===================================== */

.shopping-cart-btn .cart-number-container,
.shopping-cart-btn-container .cart-number-container,
.shopping-cart-icon-container .cart-number-container {
    background: var(--pink-strawberry) !important;
    background-color: var(--pink-strawberry) !important;
    border: 2px solid var(--white) !important;
    border-radius: 50% !important;
    box-shadow: none !important;
}

/* Cart notification number */

.shopping-cart-btn .cart-number,
.shopping-cart-btn-container .cart-number,
.shopping-cart-icon-container .cart-number {
    background: transparent !important;
    color: var(--white) !important;
}

/* Cart notification hover */

.shopping-cart-btn:hover .cart-number-container,
.shopping-cart-btn-container:hover .cart-number-container {
    background: var(--pink-hover) !important;
    background-color: var(--pink-hover) !important;
}

/* =====================================
25. POWDER PINK RECOMMENDATIONS
===================================== */

/* Main recommendations container */

#item-list-container-recommendations,
#item-list-container-recommendations .item-list,
#item-list-container-recommendations .item-list-container,
#item-list-container-recommendations .layer,
#item-list-container-recommendations #populated-item-list {
    background: #FFEAF2 !important;
    background-color: #FFEAF2 !important;
    border-color: #FFEAF2 !important;
    border-radius: 18px !important;
    box-shadow: none !important;
}

/* Remove white outer border */

#item-list-container-recommendations {
    border: none !important;
    outline: none !important;
    padding: 12px !important;
    overflow: hidden !important;
}

/* Recommendations heading */

#item-list-container-recommendations
.item-list-carousel-title,
#item-list-container-recommendations h2 {
    background: #FFEAF2 !important;
    color: #A85D7C !important;
    border-color: #FFEAF2 !important;
}

/* Recommendations carousel */

#item-list-container-recommendations
.item-list-carousel {
    background: #FFEAF2 !important;
    background-color: #FFEAF2 !important;
    border: none !important;
    border-radius: 14px !important;
    box-shadow: none !important;
}

/* Inner recommendation sections */

#item-list-container-recommendations
.item-list-carousel,
#item-list-container-recommendations
.item-list-carousel-title,
#item-list-container-recommendations
.item-list {
    border-color: #FFEAF2 !important;
}

/* Hide recommendations scrollbars
   Keeps horizontal scrolling functional */

#item-list-container-recommendations,
#item-list-container-recommendations * {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

#item-list-container-recommendations::-webkit-scrollbar,
#item-list-container-recommendations *::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
    background: transparent !important;
}

/* Recommendations scrollbar track */

#item-list-container-recommendations
::-webkit-scrollbar-track {
    display: none !important;
    background: #FFEAF2 !important;
}

/* Recommendations scrollbar thumb */

#item-list-container-recommendations
::-webkit-scrollbar-thumb {
    display: none !important;
    background: #FFEAF2 !important;
}

/* =====================================
26. STRAWBERRY CREAM FRIENDS CARDS
===================================== */

/* Friends card background and rounded corners */

ul.hlist.avatar-cards .avatar-card-container {
    background: #FFF0F5 !important;
    background-color: #FFF0F5 !important;
    border: 1px solid #F8D0DF !important;
    border-radius: 16px !important;
    overflow: hidden !important;
    box-shadow: none !important;
}

/* Keep the inside of the friend cards Strawberry Cream */

ul.hlist.avatar-cards .avatar-card-content {
    background: #FFF0F5 !important;
    background-color: #FFF0F5 !important;
    border-radius: 16px !important;
}

/* Keep the card contents within the rounded edges */

ul.hlist.avatar-cards .avatar-card-container > * {
    border-radius: inherit;
}

/* =====================================
END OF CK_777'S PASTEL PINK THEME
===================================== */
}
